      /\/health-center/i.test(url) ||
      /\/finance\//i.test(url) ||
      /\/homepage/i.test(url) ||
      /\/ads-creation/i.test(url) ||
      /\/compass/i.test(url) ||
      /\/creator/i.test(url);
    var onProduct =
