317	function ConvertTo-QingquanProductIngestItems {
318	  param(
319	    [Parameter(Mandatory = $true)] $Rows,
320	    [Parameter(Mandatory = $true)] [string]$CollectedAt,
321	    [Parameter(Mandatory = $true)] [string]$StoreId,
322	    [string]$StoreName = '',
323	    [string]$Currency = 'GBP',
324	    [string]$SourceUrl = ''
325	  )
326	  if ([string]::IsNullOrWhiteSpace($Currency)) { $Currency = 'GBP' }
327	  $items = New-Object System.Collections.ArrayList
328	  foreach ($r in @($Rows)) {
329	    $productId = ''
330	    if ($r.productId) { $productId = [string]$r.productId }
331	    elseif ($r.product_id) { $productId = [string]$r.product_id }
332	    $sellerSku = ''
333	    if ($r.sellerSku) { $sellerSku = [string]$r.sellerSku }
334	    elseif ($r.seller_sku) { $sellerSku = [string]$r.seller_sku }
335	    $productName = ''
336	    if ($r.productName) { $productName = [string]$r.productName }
337	    elseif ($r.product_name) { $productName = [string]$r.product_name }
338	    if (-not $productId) {
339	      if ($sellerSku) { $productId = "sku:$sellerSku" }
340	      elseif ($productName) { $productId = "name:$($productName.Substring(0, [Math]::Min(80, $productName.Length)))" }
341	    }
342	    if (-not $productId) { continue }
343	
344	    $stock = $null
345	    if ($null -ne $r.stockQty -and "$($r.stockQty)" -ne '') { try { $stock = [double]$r.stockQty } catch {} }
346	    $price = $null
347	    if ($null -ne $r.price -and "$($r.price)" -ne '') { try { $price = [double]$r.price } catch {} }
348	    $sales = $null
349	    if ($null -ne $r.salesQty -and "$($r.salesQty)" -ne '') { try { $sales = [double]$r.salesQty } catch {} }
350	
351	    $rowCurrency = $Currency
352	    if ($r.currency) { $rowCurrency = [string]$r.currency }
353	    elseif ($r.currencyHint) { $rowCurrency = [string]$r.currencyHint }
354	    $rowSourceUrl = $SourceUrl
355	    if ($r.sourceUrl) { $rowSourceUrl = [string]$r.sourceUrl }
356	
357	    $payload = @{
358	      product_id   = $productId
359	      product_name = $productName
360	      seller_sku   = $sellerSku
361	      status       = $(if ($r.status) { [string]$r.status } else { '' })
362	      stock_qty    = $stock
363	      price        = $price
364	      sales_qty    = $sales
365	      currency     = $rowCurrency
366	      source_url   = $rowSourceUrl
367	    }
368	
369	    [void]$items.Add([pscustomobject]@{
370	      platform        = 'tiktok'
371	      shop_id         = $StoreId
372	      shop_name       = $StoreName
373	      biz_date        = $null
374	      collected_at    = $CollectedAt
375	      idempotency_key = ("tiktok_products:{0}:{1}" -f $StoreId, $productId)
376	      payload         = $payload
377	      evidence        = @{ source_url = $rowSourceUrl }
378	    })
379	  }
